import { useEffect, useState } from "react";

export default function AdminDashboard() {
  const [activeTab, setActiveTab] = useState("menu");
  const [predictedQty, setPredictedQty] = useState(null);

  // --- Forecast API call ---
  useEffect(() => {
    if (activeTab === "forecast") {
      fetch("/api/forecast")   // change to your real endpoint
        .then(r => r.json())
        .then(d => setPredictedQty(d.qty))
        .catch(() => setPredictedQty(0));
    }
  }, [activeTab]);

  return (
    <div className="admin-page">

      {/* Header */}
      <div className="header">
        <h1>Admin Dashboard – admin</h1>
        <button className="logout-btn">Logout</button>
      </div>

      {/* Tabs */}
      <div className="tab-row">
        <TabBtn label="Menu" id="menu" activeTab={activeTab} setActiveTab={setActiveTab}/>
        <TabBtn label="Orders" id="orders" activeTab={activeTab} setActiveTab={setActiveTab}/>
        <TabBtn label="Reports" id="reports" activeTab={activeTab} setActiveTab={setActiveTab}/>
        <TabBtn label="Feedback" id="feedback" activeTab={activeTab} setActiveTab={setActiveTab}/>
        <TabBtn label="Forecast" id="forecast" activeTab={activeTab} setActiveTab={setActiveTab}/>
      </div>

      {/* Content */}
      <div className="content">

        {activeTab === "menu" && <Section title="Menu">Menu content here</Section>}
        {activeTab === "orders" && <Section title="Orders">Orders content here</Section>}
        {activeTab === "reports" && <Section title="Reports">Reports content here</Section>}
        {activeTab === "feedback" && <Section title="Feedback">Feedback content here</Section>}

        {activeTab === "forecast" && (
          <Section title="📈 Live ML Forecast">
            <div className="forecast-grid">
              <div className="forecast-card">
                <div className="label">Item Predicted Qty</div>
                <div className="value">
                  {predictedQty === null ? "Loading..." : predictedQty}
                </div>
              </div>
            </div>
          </Section>
        )}

      </div>
    </div>
  );
}

function TabBtn({ label, id, activeTab, setActiveTab }) {
  return (
    <button
      className={activeTab === id ? "tab active" : "tab"}
      onClick={() => setActiveTab(id)}
    >
      {label}
    </button>
  );
}

function Section({ title, children }) {
  return (
    <div className="card">
      <h2>{title}</h2>
      {children}
    </div>
  );
}
